package com.yuegang.zhihui.notification.application;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.notification.api.*;import java.time.*;import java.util.*;import java.util.regex.*;import javax.sql.*;import org.springframework.jdbc.core.*;
public final class NotificationService{private static final Pattern TOKEN=Pattern.compile("\\{\\{([A-Za-z][A-Za-z0-9_]{0,63})}}" );private final JdbcTemplate jdbc;public NotificationService(DataSource d){jdbc=new JdbcTemplate(d);}public NotificationView create(NotificationCommand c){long user=id(c.userId());NotificationView exists=jdbc.query("SELECT id,title,content,status,read_at,created_at FROM notification_message WHERE event_id=? AND user_id=?",r->r.next()?view(r):null,c.eventId(),user);if(exists!=null)return exists;var template=jdbc.query("SELECT title_template,content_template FROM notification_template WHERE code=? AND enabled=TRUE",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return new String[]{r.getString(1),r.getString(2)};},c.templateCode());String title=render(template[0],c.variables()),content=render(template[1],c.variables());long id=next();jdbc.update("INSERT INTO notification_message(id,event_id,user_id,template_code,title,content,status,sent_at) VALUES(?,?,?,?,?,?,'SENT',NOW(6))",id,c.eventId(),user,c.templateCode(),title,content);return jdbc.query("SELECT id,title,content,status,read_at,created_at FROM notification_message WHERE id=?",r->{r.next();return view(r);},id);}public List<NotificationView>list(long user){return jdbc.query("SELECT id,title,content,status,read_at,created_at FROM notification_message WHERE user_id=? ORDER BY created_at DESC LIMIT 100",(r,n)->view(r),user);}public void read(long user,String id){if(jdbc.update("UPDATE notification_message SET read_at=COALESCE(read_at,NOW(6)) WHERE id=? AND user_id=?",id(id),user)!=1)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);}private static String render(String t,Map<String,String>v){var m=TOKEN.matcher(t);var b=new StringBuilder();while(m.find()){String value=v.get(m.group(1));if(value==null)throw new BusinessException(ErrorCode.VALIDATION_ERROR);m.appendReplacement(b,Matcher.quoteReplacement(value));}m.appendTail(b);return b.toString();}private static NotificationView view(java.sql.ResultSet r)throws java.sql.SQLException{return new NotificationView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getString(4),r.getTimestamp(5)!=null,r.getTimestamp(6).toLocalDateTime().atOffset(ZoneOffset.UTC));}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}private static long id(String s){try{return Long.parseLong(s);}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}}
